        return 0;
    }

    int current_position = 0;
    int params_parsed = 0;

    /* Iterate through each parameter */
    for (int i = 0; i < param_count; i++) {
        /* Check if the current parameter is valid */
        if (params[i] == NULL) {
            /* NULL parameter in the array is an error */
            return -1;
        }

        /* Calculate the length of the current parameter */
        size_t param_len = strlen(params[i]);

        /* Calculate space needed: param_len + 1 for null terminator */
        /* Check for potential overflow in the calculation */
        if (param_len > (size_t)(buffer_size - 1)) {
            /* This single parameter is too large for the entire buffer */
            /* Stop processing to avoid partial writes */
            break;
        }

        /* Calculate remaining space in buffer */
        int remaining_space = buffer_size - current_position;

        /* Check if there's enough space for this parameter plus null terminator */
        /* We need param_len + 1 bytes (string + null terminator) */
        if (remaining_space < (int)(param_len + 1)) {
            /* Not enough space remaining, stop processing */
            break;
        }

        /* Safely copy the parameter to the buffer */
        memcpy(buffer + current_position, params[i], param_len);

        /* Add null terminator after the parameter */
        current_position += (int)param_len;
        buffer[current_position] = '\0';
        current_position++;

        /* Increment the count of successfully parsed parameters */
        params_parsed++;
    }

    /* Ensure the buffer is properly null-terminated even if no params were parsed */
    if (params_parsed == 0 && buffer_size > 0) {
        buffer[0] = '\0';
    }

    return params_parsed;
}
